(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["anatomy-exam-4-appendicular-musculature-quiz-version-4"]={"title":"The Appendicular Musculature — Anatomy Exam 4 — Set 4","category":"Anatomy","sem":"summer-1-2026","questions":[{"q":"The anterior compartment of the arm, containing the biceps brachii, is supplied by which nerve?","choices":["The radial nerve","The musculocutaneous nerve","The axillary nerve","The obturator nerve"],"answer":1,"exp":"The musculocutaneous nerve supplies the anterior arm flexors, including the biceps brachii, brachialis, and coracobrachialis. — Appendicular Musculature - Shahsv.pptx, Slide 92"},{"q":"The posterior compartment of the arm, containing the triceps brachii, is supplied by which nerve?","choices":["The musculocutaneous nerve","The radial nerve","The median nerve","The ulnar nerve"],"answer":1,"exp":"The radial nerve supplies the posterior arm compartment, including the triceps brachii, the elbow extensor. — Appendicular Musculature - Shahsv.pptx, Slide 92"},{"q":"The deltoid muscle receives its motor supply from which nerve, commonly injured in shoulder dislocation?","choices":["The axillary nerve","The thoracodorsal nerve","The long thoracic nerve","The femoral nerve"],"answer":0,"exp":"The axillary nerve supplies the deltoid and teres minor and is vulnerable in anterior shoulder dislocation and surgical-neck fractures. — Appendicular Musculature - Shahsv.pptx, Slide 12"},{"q":"The latissimus dorsi is innervated by which nerve?","choices":["The axillary nerve","The suprascapular nerve","The thoracodorsal nerve","The musculocutaneous nerve"],"answer":2,"exp":"The thoracodorsal nerve supplies the latissimus dorsi, the large arm extensor and adductor of the back. — Appendicular Musculature - Shahsv.pptx, Slide 12"},{"q":"Most muscles of the anterior forearm are supplied by which nerve, with the flexor carpi ulnaris an exception?","choices":["The radial nerve","The axillary nerve","The obturator nerve","The median nerve"],"answer":3,"exp":"Most anterior forearm flexors are supplied by the median nerve, with the flexor carpi ulnaris and part of the flexor digitorum profundus supplied by the ulnar nerve. — Appendicular Musculature - Shahsv.pptx, Slide 29"},{"q":"The muscles of the posterior forearm compartment (the extensors) are supplied mainly by which nerve?","choices":["The median nerve","The radial nerve","The ulnar nerve","The musculocutaneous nerve"],"answer":1,"exp":"The posterior forearm extensor compartment is supplied by the radial nerve and its deep branch. — Appendicular Musculature - Shahsv.pptx, Slide 92"},{"q":"Most of the intrinsic muscles of the hand, including the interossei and hypothenar muscles, are supplied by which nerve?","choices":["The ulnar nerve","The radial nerve","The axillary nerve","The femoral nerve"],"answer":0,"exp":"The ulnar nerve supplies most intrinsic hand muscles, including the interossei, hypothenar muscles, and medial lumbricals. — Appendicular Musculature - Shahsv.pptx, Slide 47"},{"q":"Which nerve supplies the quadriceps femoris of the anterior thigh?","choices":["The sciatic nerve","The femoral nerve","The obturator nerve","The superior gluteal nerve"],"answer":1,"exp":"The femoral nerve supplies the anterior thigh muscles, including the quadriceps femoris and sartorius. — Appendicular Musculature - Shahsv.pptx, Slide 67"},{"q":"Which nerve supplies most of the medial (adductor) compartment of the thigh?","choices":["The femoral nerve","The tibial nerve","The axillary nerve","The obturator nerve"],"answer":3,"exp":"The obturator nerve supplies most of the medial thigh adductor muscles. — Appendicular Musculature - Shahsv.pptx, Slide 60"},{"q":"Which nerve supplies the gluteus medius and minimus, whose weakness causes a Trendelenburg sign?","choices":["The superior gluteal nerve","The inferior gluteal nerve","The femoral nerve","The obturator nerve"],"answer":0,"exp":"The superior gluteal nerve supplies the gluteus medius and minimus and the tensor fasciae latae, hip abductors that steady the pelvis. — Appendicular Musculature - Shahsv.pptx, Slide 55"},{"q":"Which nerve supplies the gluteus maximus, the main thigh extensor?","choices":["The superior gluteal nerve","The tibial nerve","The inferior gluteal nerve","The median nerve"],"answer":2,"exp":"The inferior gluteal nerve supplies the gluteus maximus, the powerful extensor of the thigh. — Appendicular Musculature - Shahsv.pptx, Slide 55"},{"q":"The hamstrings of the posterior thigh are supplied mainly by which nerve?","choices":["The femoral nerve by itself","The obturator nerve by itself","The tibial part of the sciatic nerve","The superior gluteal nerve trunk"],"answer":2,"exp":"The hamstrings are supplied mainly by the tibial division of the sciatic nerve (the short head of biceps femoris by the common fibular division). — Appendicular Musculature - Shahsv.pptx, Slide 69"},{"q":"The anterior compartment of the leg, which dorsiflexes the foot, is supplied by which nerve?","choices":["The tibial nerve","The deep fibular nerve","The superficial fibular nerve","The obturator nerve"],"answer":1,"exp":"The deep fibular (deep peroneal) nerve supplies the anterior leg compartment that dorsiflexes the foot and extends the toes. — Appendicular Musculature - Shahsv.pptx, Slide 103"},{"q":"The lateral compartment of the leg, which everts the foot, is supplied by which nerve?","choices":["The deep fibular nerve","The posterior tibial nerve","The superficial fibular nerve","The femoral nerve of the thigh"],"answer":2,"exp":"The superficial fibular (peroneal) nerve supplies the lateral leg compartment, whose fibularis muscles evert the foot. — Appendicular Musculature - Shahsv.pptx, Slide 103"},{"q":"The posterior compartment of the leg, which plantarflexes the foot, is supplied by which nerve?","choices":["The deep fibular nerve","The superficial fibular nerve","The obturator nerve","The tibial nerve"],"answer":3,"exp":"The tibial nerve supplies the posterior leg compartment, whose muscles plantarflex the foot and flex the toes. — Appendicular Musculature - Shahsv.pptx, Slide 103"},{"q":"Which small muscle of the deep gluteal region is a landmark that the sciatic nerve usually passes beneath?","choices":["The gluteus maximus","The piriformis","The adductor magnus","The rectus femoris"],"answer":1,"exp":"The piriformis is a deep gluteal lateral rotator beneath which the sciatic nerve typically passes as it leaves the pelvis. — Appendicular Musculature - Shahsv.pptx, Slide 57"},{"q":"The iliopsoas is formed by the union of which two muscles?","choices":["The gluteus maximus and medius","The psoas major and the iliacus","The biceps femoris and gracilis","The soleus and gastrocnemius"],"answer":1,"exp":"The iliopsoas is formed by the psoas major, arising from the lumbar vertebrae, and the iliacus, arising from the iliac fossa. — Appendicular Musculature - Shahsv.pptx, Slide 63"},{"q":"Which long, strap-like muscle crosses the thigh obliquely and is described as the longest muscle in the body?","choices":["The sartorius","The gracilis muscle","The rectus femoris","The gastrocnemius"],"answer":0,"exp":"The sartorius is the long, strap-like muscle that crosses the anterior thigh obliquely and is the longest muscle in the body. — Appendicular Musculature - Shahsv.pptx, Slide 54"},{"q":"The soleus and gastrocnemius are sometimes grouped together under which common name?","choices":["The triceps surae","The quadriceps femoris","The rotator cuff","The hamstring group"],"answer":0,"exp":"The gastrocnemius and soleus together are called the triceps surae, sharing the calcaneal tendon to plantarflex the foot. — Appendicular Musculature - Shahsv.pptx, Slide 75"},{"q":"Which deep posterior leg muscle inverts the foot and supports the medial arch, inserting on several tarsal bones?","choices":["The tibialis posterior","The tibialis anterior","The fibularis brevis","The extensor hallucis longus"],"answer":0,"exp":"The tibialis posterior, deep in the posterior leg, inverts the foot and supports the medial longitudinal arch. — Appendicular Musculature - Shahsv.pptx, Slide 75"},{"q":"The intrinsic muscles of the foot mainly serve which function?","choices":["Flexing the elbow joint tightly","Rotating the scapula on the back","Extending the wrist and hand","Supporting the arches and the toes"],"answer":3,"exp":"The intrinsic foot muscles support the arches of the foot and produce fine movements of the toes. — Appendicular Musculature - Shahsv.pptx, Slide 83"},{"q":"Which small muscle deep to the pectoralis major depresses the scapula and elevates the ribs?","choices":["The pectoralis minor","The serratus anterior","The trapezius muscle","The deltoid muscle"],"answer":0,"exp":"The pectoralis minor lies deep to the pectoralis major and depresses the scapula while helping elevate the ribs. — Appendicular Musculature - Shahsv.pptx, Slide 7"},{"q":"Which two rotator cuff muscles are the main lateral rotators of the arm?","choices":["The subscapularis and supraspinatus","The deltoid and pectoralis major","The infraspinatus and teres minor","The biceps and coracobrachialis"],"answer":2,"exp":"The infraspinatus and teres minor are the rotator cuff muscles that laterally rotate the arm. — Appendicular Musculature - Shahsv.pptx, Slide 12"},{"q":"Which forearm muscle, named for its action, rotates the forearm so the palm faces posteriorly?","choices":["The supinator muscle","The brachioradialis","The extensor digitorum","The pronator teres"],"answer":3,"exp":"The pronator teres pronates the forearm, turning the palm to face posteriorly, assisted by the pronator quadratus. — Appendicular Musculature - Shahsv.pptx, Slide 29"},{"q":"Which quadriceps muscle forms the teardrop-shaped bulge on the medial side just above the knee?","choices":["The vastus lateralis","The rectus femoris","The biceps femoris","The vastus medialis"],"answer":3,"exp":"The vastus medialis forms the teardrop-shaped muscle bulge on the medial side of the thigh just above the knee. — Appendicular Musculature - Shahsv.pptx, Slide 67"},{"q":"Muscles that produce the same movement at a joint are functionally described as what to each other?","choices":["Antagonists opposing the movement","Fixators of distant joints","Sphincters closing an opening","Synergists (agonists working together)"],"answer":3,"exp":"Muscles that cooperate to produce the same movement are synergists, or agonists working together at a joint. — Appendicular Musculature - Shahsv.pptx, Slide 19"},{"q":"The gluteal muscles as a group act at which joint?","choices":["The knee joint","The ankle joint","The hip joint","The shoulder joint"],"answer":2,"exp":"The gluteal muscles act at the hip joint, producing extension, abduction, and rotation of the thigh. — Appendicular Musculature - Shahsv.pptx, Slide 53"},{"q":"A rotator cuff tear most directly impairs which function of the shoulder?","choices":["Flexing the fingers into a fist","Dorsiflexing the foot at the ankle","Stabilizing and rotating the arm","Extending the knee joint"],"answer":2,"exp":"The rotator cuff stabilizes the humeral head in the glenoid and rotates the arm, so a tear impairs shoulder stability and rotation. — Appendicular Musculature - Shahsv.pptx, Slide 11"},{"q":"Which large tendon, formed by the calf muscles, is the strongest and thickest tendon in the body?","choices":["The calcaneal (Achilles) tendon","The patellar tendon of the knee","The biceps tendon of the arm","The quadriceps tendon above"],"answer":0,"exp":"The calcaneal, or Achilles, tendon formed by the gastrocnemius and soleus is the strongest and thickest tendon in the body. — Appendicular Musculature - Shahsv.pptx, Slide 75"},{"q":"The muscles of the leg are divided into anterior, lateral, and which third compartment?","choices":["The medial compartment","The posterior compartment","The gluteal compartment","The pelvic compartment"],"answer":1,"exp":"The leg is divided into anterior, lateral, and posterior compartments, the posterior one containing the plantarflexors of the foot. — Appendicular Musculature - Shahsv.pptx, Slide 103"}]};
